"use client";

import { useState } from "react";
import { ChevronDown, Info, MessageSquare, Target, Trash2 } from "lucide-react";
import { cn } from "@/lib/utils";

const AI_DISCLAIMER =
  "The values provided above are approximate estimations generated by AI and are not exact. The organization does not assume any responsibility for their absolute accuracy.";

function Chip({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1 whitespace-nowrap rounded-full px-2.5 py-1 text-xs font-medium tabular-nums",
        className
      )}
    >
      {children}
    </span>
  );
}

/**
 * One diet/activity log on the History page. Collapsed it is a single row
 * (time, what was logged, headline figures); clicking it opens the AI
 * breakdown. `framed` renders it as a standalone tile for the grid view,
 * otherwise it is a row meant to sit inside a divided panel.
 */
export function HistoryLogEntry({
  log,
  onDelete,
  framed = false,
}: {
  log: any;
  onDelete: (id: string) => void;
  framed?: boolean;
}) {
  const [expanded, setExpanded] = useState(false);

  const foods: any[] = Array.isArray(log.parsedData?.foods) ? log.parsedData.foods : [];
  const exercises: any[] = Array.isArray(log.parsedData?.exercises) ? log.parsedData.exercises : [];
  const feedback = log.aiFeedback || log.parsedData?.ai_feedback;

  const macro = foods.reduce(
    (acc, f) => ({
      protein: acc.protein + (Number(f.protein) || 0),
      carbs: acc.carbs + (Number(f.carbs) || 0),
      fats: acc.fats + (Number(f.fats) || 0),
    }),
    { protein: 0, carbs: 0, fats: 0 }
  );

  const time = new Date(log.date).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  const showIn = log.totalCaloriesIn > 0 || (!(log.totalCaloriesOut > 0) && !(log.waterMl > 0));

  return (
    <article
      className={cn(
        "cursor-pointer px-4 py-4 transition-colors md:px-6",
        framed ? "panel" : "hover:bg-surface/50",
        framed && expanded && "border-foreground/25"
      )}
      onClick={() => setExpanded(!expanded)}
    >
      <div className="flex items-start gap-3 md:gap-5">
        <time className="label-mono hidden w-[4.25rem] shrink-0 pt-1 tabular-nums md:block">{time}</time>

        <div className="min-w-0 flex-1">
          <p className="label-mono mb-1.5 tabular-nums md:hidden">{time}</p>
          {!expanded && <p className="truncate text-[15px] font-medium leading-snug">{log.rawText}</p>}
          {expanded && <p className="text-[15px] font-medium leading-relaxed">{log.rawText}</p>}

          <div className="mt-2 flex flex-wrap items-center gap-1.5">
            {showIn && (
              <Chip className="bg-surface text-foreground">
                +{log.totalCaloriesIn}
                <span className="font-normal text-muted-foreground">kcal</span>
              </Chip>
            )}
            {log.totalCaloriesOut > 0 && (
              <Chip className="bg-burn/12 text-burn">
                -{log.totalCaloriesOut}
                <span className="font-normal opacity-80">kcal</span>
              </Chip>
            )}
            {log.waterMl > 0 && <Chip className="bg-water/12 text-water">{log.waterMl}ml</Chip>}
            {foods.length > 0 && (
              <>
                <Chip className="bg-protein/12 text-protein">P {Math.round(macro.protein)}g</Chip>
                <Chip className="bg-carbs/12 text-carbs">C {Math.round(macro.carbs)}g</Chip>
                <Chip className="bg-fats/12 text-fats">F {Math.round(macro.fats)}g</Chip>
              </>
            )}
          </div>
        </div>

        <div className="-mr-1.5 flex shrink-0 items-center">
          <button
            type="button"
            aria-label="Delete entry"
            className="grid size-10 place-items-center rounded-full text-muted-foreground transition-colors hover:bg-priority-high-bg hover:text-destructive"
            onClick={(e) => {
              e.stopPropagation();
              onDelete(log.id);
            }}
          >
            <Trash2 className="size-4" />
          </button>
          <button
            type="button"
            aria-expanded={expanded}
            aria-label={expanded ? "Hide details" : "Show details"}
            className="grid size-10 place-items-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
            onClick={(e) => {
              e.stopPropagation();
              setExpanded(!expanded);
            }}
          >
            <ChevronDown className={cn("size-4 transition-transform duration-200", expanded && "rotate-180")} />
          </button>
        </div>
      </div>

      {expanded && log.parsedData && (
        <div className="mt-4 space-y-3 animate-fade-in md:ml-[5.5rem]">
          {feedback && (
            <div className="rounded-2xl bg-surface p-4">
              <p className="label-mono flex items-center gap-1.5">
                <MessageSquare className="size-3.5" /> Coach analysis
              </p>
              <p className="mt-2 text-[15px] leading-relaxed">{feedback}</p>
            </div>
          )}

          {log.parsedData.next_step && (
            <div className="rounded-2xl bg-lime p-4 text-lime-foreground">
              <p className="flex items-center gap-1.5 font-mono text-[11px] uppercase tracking-[0.1em] opacity-70">
                <Target className="size-3.5" /> Next step
              </p>
              <p className="mt-1.5 text-[15px] font-medium leading-snug">{log.parsedData.next_step}</p>
            </div>
          )}

          <dl className="grid grid-cols-2 gap-3">
            <div className="rounded-2xl border border-border p-4">
              <dt className="label-mono">In</dt>
              <dd className="numeral mt-2 text-2xl">
                {log.totalCaloriesIn}
                <span className="ml-1 text-xs font-normal tracking-normal text-muted-foreground">kcal</span>
              </dd>
            </div>
            <div className="rounded-2xl border border-border p-4">
              <dt className="label-mono">Out</dt>
              <dd className="numeral mt-2 text-2xl text-burn">
                {log.totalCaloriesOut}
                <span className="ml-1 text-xs font-normal tracking-normal text-muted-foreground">kcal</span>
              </dd>
            </div>
          </dl>

          {foods.length > 0 && (
            <div>
              <p className="label-mono mb-2">Foods tracked</p>
              <ul className="divide-y divide-border overflow-hidden rounded-2xl border border-border">
                {foods.map((food: any, i: number) => (
                  <li
                    key={i}
                    className="flex flex-col gap-1.5 p-3.5 text-sm sm:flex-row sm:items-center sm:justify-between sm:gap-4"
                  >
                    <div className="flex min-w-0 items-start justify-between gap-3">
                      <span className="font-medium">{food.name}</span>
                      <span className="shrink-0 tabular-nums sm:hidden">{food.calories} kcal</span>
                    </div>
                    <div className="flex shrink-0 flex-wrap items-center gap-x-3 gap-y-1 text-[13px] tabular-nums text-muted-foreground">
                      <span>
                        <span className="font-medium text-protein">{food.protein}g</span> protein
                      </span>
                      <span>
                        <span className="font-medium text-carbs">{food.carbs}g</span> carbs
                      </span>
                      <span>
                        <span className="font-medium text-fats">{food.fats}g</span> fat
                      </span>
                      <span className="hidden w-20 text-right text-sm text-foreground sm:inline">
                        {food.calories} kcal
                      </span>
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {exercises.length > 0 && (
            <div>
              <p className="label-mono mb-2">Activity tracked</p>
              <ul className="divide-y divide-border overflow-hidden rounded-2xl border border-border">
                {exercises.map((exercise: any, i: number) => (
                  <li key={i} className="flex items-center justify-between gap-3 p-3.5 text-sm">
                    <span className="min-w-0 truncate font-medium">{exercise.name}</span>
                    <span className="flex shrink-0 items-center gap-3 tabular-nums">
                      <span className="text-[13px] text-muted-foreground">
                        {exercise.duration_minutes ?? exercise.duration} mins
                      </span>
                      <span className="text-burn">{exercise.calories_burned ?? exercise.calories} kcal</span>
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          <p className="flex items-start gap-2 pt-1 text-xs leading-relaxed text-muted-foreground">
            <Info className="mt-0.5 size-3.5 shrink-0" />
            {AI_DISCLAIMER}
          </p>
        </div>
      )}
    </article>
  );
}
